import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Upanayana source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/22-upanayana-profile.md","filePath":"reference/22-upanayana-profile.md","lastUpdated":1788593217000}'),n={name:"reference/22-upanayana-profile.md"};function d(i,a,s,c,l,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="upanayana-source-profile" tabindex="-1">Upanayana source profile <a class="header-anchor" href="#upanayana-source-profile" aria-label="Permalink to &quot;Upanayana source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The sacred-thread profile is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter VIII, “Post-natal ceremonies” / “Investiture of sacred thread (Upanayanam),” internal printed pages 24–25 (physical PDF pages 27–28) in the inspected 2020 Chistabo derivative:</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">inspected 2020 Chistabo derivative</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture. Eligibility, age, ritual procedure and lineage-specific exceptions belong to the family&#39;s sampradaya and officiating Acharya; the finder only screens time.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Perform in the 5th or 8th year, with later-age limits and exceptions</td><td><code>manual_checks</code></td><td>Age and community/lineage rules are not finder inputs.</td></tr><tr><td>Magha, Phalguna, Chaitra and Vaishakha are good</td><td><code>allowed_maasams</code></td><td>Other lunar months reject the day.</td></tr><tr><td>Surya&#39;s northern course, Makara through Mithuna</td><td><code>allowed_solar_signs</code></td><td>The exact six-Rasi allow-list rejects a day outside Uttarayana.</td></tr><tr><td>Different admitted Tithis in Shukla and Krishna Paksha</td><td><code>allowed_tithi_names</code></td><td>Exact Paksha-qualified names prevent a Shukla rule from leaking into Krishna Paksha. The delayed-age Chaturdashi exception remains manual.</td></tr><tr><td>Monday, Wednesday, Thursday and Friday propitious; reject Wednesday if Budha combust</td><td><code>allowed_varas</code>; <code>manual_checks</code></td><td>Four best weekdays are admitted; conditional combustion remains visible because the browser feed lacks a reliable slot-level Budha-combustion fact.</td></tr><tr><td>Sixteen named Nakshatras are good</td><td><code>allowed_nakshatras</code></td><td>Unlisted active slot-time Nakshatras reject a candidate.</td></tr><tr><td>Seven rising Rasis are good</td><td><code>allowed_lagnas</code></td><td>Only the seven stated Rasis survive slot-time Lagna screening.</td></tr><tr><td>Ceremony before noon</td><td><code>forenoon_only</code></td><td>The entire named Muhurta must end by local solar noon; night search returns none.</td></tr><tr><td>Detailed Chandra, malefic, house and Yoga conditions</td><td><code>manual_checks</code></td><td>Full election-chart occupancy, aspects, dignity and exceptions remain practitioner-reviewed.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>Shared samskara exclusions, hard avoid windows, Tithi-family ranking, personal scoring and relative tiers are not established by this locator. MCP exposes <code>muhurta.upanayana</code>, exact Tithi/solar-Rasi constraints and every manual check; the browser consumes the same generated contract.</p>',9)])])}const m=e(n,[["render",d]]);export{p as __pageData,m as default};
